    # GET /v1/trust/credential-status/receipt-sync/history：只读
    # 查询某同步来源（签名方）已落盘的外系统凭证状态回执消费事件
    # 在指定时点的历史页。
    # 查询参数仅允许 signer_did、at、limit、after 且均只能出现
    # 一次：signer_did 必填非空；at 缺省取该来源同步检查点
    # next_after、须为 ASCII 非负整数；limit 缺省 50、限 1..200；
    # after 缺省 0、须为 ASCII 非负整数。空值、重复、未知参数、
    # 非 ASCII 数字、符号、越界或 after>at 均 400 且仅
    # {"error":"请求非法"}；该来源未同步（含跨租户）404 仅
    # {"error":"同步来源不存在"}，at 超过检查点 409 仅
    # {"error":"同步游标冲突"}。200 键序恰为 signer_did、at、
    # events、next_after；以请求初原子快照取 cursor<=at 的事件，
    # 再按 cursor>after 升序取前 limit 项，事件键序恰为 cursor、
    # receipt_id、verifier_did、nonce、consumed_at（cursor 为正
    # 整数，其余四值为非空字符串，consumed_at 为 UTC 秒精度 Z）；
    # 空页 next_after 等于 after，否则等于末项 cursor。同一 at
    # 的分页不受后续同步影响，重启逐字节一致。
    # 纯只读：不推进检查点、不改判重索引、不记审计、不触发落盘。
    try:
        params = parse_qs(query, keep_blank_values=True)
        allowed = {"signer_did", "at", "limit", "after"}
        if set(params) - allowed:
            raise ValidationError("请求非法")

        def _single(name: str) -> Optional[str]:
            values = params.get(name)
            if values is None:
                return None
            if len(values) != 1:
                raise ValidationError("请求非法")
            return values[0]

        signer_did = _single("signer_did")
        if signer_did is None or not signer_did:
            raise ValidationError("请求非法")

        at_raw = _single("at")
        at = (
            _parse_nonneg_int(at_raw, "at")
            if at_raw is not None
            else None
        )

        limit_raw = _single("limit")
        if limit_raw is not None:
            limit = _parse_nonneg_int(limit_raw, "limit")
            if not 1 <= limit <= 200:
                raise ValidationError("请求非法")
        else:
            limit = 50

        after_raw = _single("after")
        if after_raw is not None:
            after = _parse_nonneg_int(after_raw, "after")
        else:
            after = 0

        if at is not None and after > at:
            raise ValidationError("请求非法")
    except ValidationError:
        raise ValidationError("请求非法")

    try:
        at_value, events, next_after = (
            store.list_credential_status_receipt_sync_history(
                tenant, signer_did, at, after, limit
            )
        )
    except ValidationError:
        # at 缺省时取检查点：after 超过生效 at 同样为请求非法。
        raise ValidationError("请求非法")
    self._send_json(
        200,
        {
            "signer_did": signer_did,
            "at": at_value,
            "events": events,
            "next_after": next_after,
        },
    )

def _get_trust_credential_status_receipt_sync_receipt(
    self, tenant: str, query: str
) -> None:
    # GET /v1/trust/credential-status/receipt-sync/receipt：凭证
    # 状态回执消费同步进度签名回执（纯只读），供接收方离线证明
    # 来源检查点。
    # 参数、请求键集、类型、状态码、键序、错误优先级、NDJSON、
    # 规范化 JSON 与 ES256 协议完整复用
    # GET /v1/trust/presentation-sync/receipt，仅状态空间与事件
    # 五键不同：原子读取该来源凭证状态回执消费同步检查点及
    # cursor<=next_after 的全部已落盘状态回执消费事件（按 cursor
    # 升序），逐行沿用既有 receipt-sync history 五键（cursor、
    # receipt_id、verifier_did、nonce、consumed_at）NDJSON 编码，
    # digest 为行字节的 SHA-256 小写 64 位 hex。同步来源或验证
    # 者 DID 不存在（含跨租户）404，验证者已停用 409。不推进
    # 检查点、不写状态或审计；重启后 receipt 与 digest 相同且
    # 签名可验。
    try:
        params = parse_qs(query, keep_blank_values=True)
        allowed = {"signer_did", "verifier_did", "nonce"}
        if set(params) - allowed:
            raise ValidationError("请求非法")

        def _single(name: str) -> Optional[str]:
            values = params.get(name)
            if values is None:
                return None
            if len(values) != 1:
                raise ValidationError("请求非法")
            return values[0]

        signer_did = _single("signer_did")
        if signer_did is None or not signer_did:
            raise ValidationError("请求非法")
        verifier_did = _single("verifier_did")
        if verifier_did is None or not verifier_did:
            raise ValidationError("请求非法")
        nonce = _single("nonce")
        if nonce is None or not nonce:

                if nonce is None or not nonce:
                    raise ValidationError("请求非法")
                if not 1 <= len(nonce) <= 256:
                    raise ValidationError("请求非法")
            except ValidationError:
                raise ValidationError("请求非法")

            (
                next_after,
                events,
                verifier_key_version,
                verifier_private_pem,
            ) = store.get_credential_status_receipt_sync_receipt_material(
                tenant, signer_did, verifier_did
            )

            digest = hashlib.sha256(
                _receipt_consumption_ndjson_bytes(events)
            ).hexdigest()
            receipt = {
                "signer_did": signer_did,
                "next_after": next_after,
                "digest": digest,
                "verifier_did": verifier_did,
                "verifier_key_version": verifier_key_version,
                "nonce": nonce,
            }
            signature = crypto.sign(receipt, verifier_private_pem)
            self._send_json(200, {"receipt": receipt, "signature": signature})

        def _post_trust_credential_status_receipt_sync_receipt_verify(
            self, tenant: str
        ) -> None:
            # POST /v1/trust/credential-status/receipt-sync/receipt/verify：
            # 验真凭证状态回执消费同步进度签名回执（纯只读）。
            # 请求键集、类型、状态码、键序、错误优先级、NDJSON、规范化
            # JSON 与 ES256 协议完整复用
            # POST /v1/trust/presentation-sync/receipt/verify，唯一差异
            # 为阶段四验真锚点用途：本租户同 verifier_did/版本的 active
            # 信任锚点须含 status 用途（原接口为 vp）。失败原因及顺序
            # 沿用原接口（回执非法 -> nonce 错误 -> 摘要错误 -> 锚点
            # 不可用 -> 签名格式错误 -> 签名校验失败），成功仅
            # {"valid":true}。不解析 ndjson，不写状态、游标或审计；
            # 重启稳定。
            try:
                data = self._read_json()
                if set(data) != {"receipt", "signature", "ndjson", "nonce"}:
                    raise ValidationError("请求非法")
                receipt = data["receipt"]
                signature = data["signature"]
                ndjson = data["ndjson"]
                nonce = data["nonce"]
                if not isinstance(receipt, dict):
                    raise ValidationError("请求非法")
                if not isinstance(signature, str) or not signature:
                    raise ValidationError("请求非法")
                if not isinstance(ndjson, str):
                    raise ValidationError("请求非法")
                if not isinstance(nonce, str) or not 1 <= len(nonce) <= 256:
                    raise ValidationError("请求非法")
            except (ValidationError, ValueError):
                # ValueError：JSON 内超长十进制整数触发位数上限。
                raise ValidationError("请求非法")

            reason = self._verify_presentation_sync_receipt_item(
                tenant,
                receipt,
                signature,
                ndjson,
                nonce,
                required_use="status",
            )
            if reason is not None:
                self._send_json(200, {"valid": False, "reason": reason})
                return
            self._send_json(200, {"valid": True})

        def _get_trust_credential_status(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}?issuer_did=...：issuer_did 须唯一
            # 且非空，否则 400；未同步（含他租户双键）404，跨租户不可
            # 探测。已同步仅返回 status、reason、updated_at。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_synced_credential_status(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "status": record.status,
                    "reason": record.reason,
                    "updated_at": record.updated_at,
                },
            )

        def _get_trust_imported_credential(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET /v1/trust/credentials/imported/{credential_id}
            # ?issuer_did=...：issuer_did 须唯一且非空，缺失/重复/空值
            # 一律 400；未导入、跨租户或 issuer_did 不匹配（含他租户
            # 双键）404，存在性不可探测。成功 200 返回键序
            # issuer_did,credential_id,body,signature。纯只读，不写状态、
            # 不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)
            values = params.get("issuer_did")
            if values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )
            record = store.get_imported_credential(
                tenant, issuer_did, credential_id
            )
            self._send_json(
                200,
                {
                    "issuer_did": record.issuer_did,
                    "credential_id": record.credential_id,
                    "body": record.body,
                    "signature": record.signature,
                },
            )

        def _get_trust_credential_status_history(
            self, tenant: str, credential_id: str, query: str
        ) -> None:
            # GET .../{credential_id}/history?issuer_did=...&limit=&after=
            # issuer_did 须唯一且非空，否则 400；limit 缺省 50，须为
            # 1..200 的 ASCII 十进制整数；after 缺省 0，须为非负 ASCII
            # 十进制整数；重复/非法一律 400。未同步双键（含他租户）404。
            # 只读：不写任何状态、不记审计。
            if not credential_id:
                raise ValidationError("路径缺少 credential_id")
            params = parse_qs(query, keep_blank_values=True)

            issuer_values = params.get("issuer_did")
            if issuer_values is None:
                raise ValidationError("查询参数 issuer_did 必填")
            if len(issuer_values) != 1:
                raise ValidationError("查询参数 issuer_did 只能提供一次")
            issuer_did = issuer_values[0]
            if not issuer_did:
                raise ValidationError(
                    "查询参数 issuer_did 必须为非空字符串"
                )

            limit_values = params.get("limit")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError(
                        "查询参数 limit 须在 1 到 200 之间"
                    )
            else:
                limit = 50

            after_values = params.get("after")
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_synced_credential_status_history(
                tenant, issuer_did, credential_id, after, limit
            )
            self._send_json(
                200,
                {
                    "issuer_did": issuer_did,
                    "credential_id": credential_id,
                    "events": [
                        {
                            "status": event.status,
                            "reason": event.reason,
                            "updated_at": event.updated_at,
                            "issuer_key_version": event.issuer_key_version,
                            "audit_seq": event.audit_seq,
                            "audit_timestamp": event.audit_timestamp,
                            "cursor": event.cursor,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

        def _get_audit(self, tenant: str, query: str) -> None:            # GET /v1/audit?limit=&after=：租户内按 seq 升序。
            # limit 缺省 50，须为 1..200 的整数；after 缺省 0，须为
            # 非负整数；非法一律 400。返回 events 与 next_after，
            # 空页 next_after 保持 after。
            params = parse_qs(query, keep_blank_values=True)
            limit_values = params.get("limit")
            after_values = params.get("after")
            if limit_values is not None:
                if len(limit_values) != 1:
                    raise ValidationError("查询参数 limit 只能提供一次")
                limit = _parse_nonneg_int(limit_values[0], "limit")
                if not 1 <= limit <= 200:
                    raise ValidationError("查询参数 limit 须在 1 到 200 之间")
            else:
                limit = 50
            if after_values is not None:
                if len(after_values) != 1:
                    raise ValidationError("查询参数 after 只能提供一次")
                after = _parse_nonneg_int(after_values[0], "after")
            else:
                after = 0

            events, next_after = store.list_audit(tenant, after, limit)
            self._send_json(
                200,
                {
                    "events": [
                        {
                            "seq": event.seq,
                            "timestamp": event.timestamp,
                            "tenant_id": event.tenant_id,
                            "action": event.action,
                            "resource_type": event.resource_type,
                            "resource_id": event.resource_id,
                        }
                        for event in events
                    ],
                    "next_after": next_after,
                },
            )

